    onSettled: (_data, _err, { userType }) => {
      qc.invalidateQueries({ queryKey: issueKeys.subscribersAll() });
      const wsId = getCurrentWsId();
      if (wsId && userType === "member") void refreshSubscribedIssues(qc, wsId);
    },
  });
}

